+                        switch (curr) {
+                            case '\\', '^', '$', '.', '*', '?', '+', '|', '(', ')', '[', ']', '{', '}' -> regex.append('\\');
+                        }
+                        regex.append(curr);
+                    }
+                }
+                escaped = false;
+            }
+        }
